#!/usr/bin/env bash
# Re-check the restricted channels from this computer and open a pull request with the results.
#
#   bash scripts/verify_regional_local.sh asia-pk
#   bash scripts/verify_regional_local.sh asia-pk GEO_RESTRICTED,UNKNOWN,TIMEOUT,restricted
#
# The label may also come from the REGIONAL_LABEL environment variable. Needs git, python3 (3.11 or newer) and,
# for the pull request, the GitHub CLI (gh) logged in. See docs/REGIONAL_CHECKS.md.
# Only state/regional/<label>.json is committed. Playlists and reports are regenerated by the daily workflow.
set -euo pipefail

label="${1:-${REGIONAL_LABEL:-}}"
only="${2:-GEO_RESTRICTED,UNKNOWN,TIMEOUT,restricted}"
if ! printf '%s' "$label" | grep -Eq '^[a-z0-9][a-z0-9-]{1,31}$'; then
  echo "usage: bash scripts/verify_regional_local.sh <label> [selectors]   (label: a-z, 0-9, '-', e.g. asia-pk)" >&2
  exit 2
fi

cd "$(git rev-parse --show-toplevel)"
if [ -n "$(git status --porcelain --untracked-files=no)" ]; then
  echo "Your working tree has uncommitted changes; commit or stash them first." >&2
  exit 1
fi

branch="regional/${label}-$(date -u +%Y%m%d)"
git fetch --quiet origin main
git checkout --quiet -B "$branch" origin/main

if [ ! -x .venv-regional/bin/python ]; then
  python3 -m venv .venv-regional
fi
.venv-regional/bin/python -m pip install --quiet -r requirements.txt

.venv-regional/bin/python scripts/verify.py --location-label "$label" --only "$only"

file="state/regional/${label}.json"
if [ ! -f "$file" ] || [ -z "$(git status --porcelain -- "$file")" ]; then
  echo "Nothing to commit (no matching channels, or no new results)."
  git checkout --quiet -
  exit 0
fi

git add -- "$file"
git commit --quiet -m "Regional verification results ($label)"
git push --quiet --set-upstream origin "$branch"

title="Regional verification results ($label)"
body="Re-check of the restricted channels from the location \`$label\`. Only state/regional/$label.json changes; the playlists and reports pick it up on the next daily run."
if command -v gh >/dev/null 2>&1; then
  gh pr create --base main --head "$branch" --title "$title" --body "$body"
else
  echo "Branch pushed. Open a pull request from '$branch' into main on GitHub."
fi
